"""Build portfolio content pages. Articles and isolated demos are maintained separately."""
from pathlib import Path
from html import escape
ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://mobolaji.builtbykora.com'
EMAIL = 'mailto:bjfifi1@gmail.com'
GH = 'https://github.com/korastudios/Kora'

def link(text, href, primary=False):
    return f'<a class="action{" action--primary" if primary else ""}" href="{href}">{text} <span aria-hidden="true">↗</span></a>'

def image(src, alt, cls='', eager=False):
    from PIL import Image
    with Image.open(ROOT/src.lstrip('/')) as im: w,h=im.size
    return f'<img class="{cls}" src="{src}" alt="{escape(alt)}" width="{w}" height="{h}" loading="{"eager" if eager else "lazy"}" decoding="async">'

def page(route, title, description, body):
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if route==url else '')+f'>{label}</a>' for label,url in [('Work','/projects/'),('About','/about/'),('Resume','/assets/resume.pdf'),('Contact',EMAIL)])
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Mobolaji Ogunbiyi</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#ffffff"><link rel="canonical" href="{BASE}{route}"><meta property="og:title" content="{escape(title)} — Mobolaji Ogunbiyi"><meta property="og:description" content="{escape(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{BASE}{route}"><meta property="og:image" content="{BASE}/assets/projects/kora-interactive-sample.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/styles.css?v=rebuild1"><script defer src="/script.js"></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header" data-header><div class="shell header-inner"><a class="wordmark" href="/">Mobolaji Ogunbiyi<span class="wordmark-dot" aria-hidden="true">.</span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="primary-nav" data-menu-button>Menu</button><nav class="primary-nav" id="primary-nav" aria-label="Primary" data-nav>{nav}</nav></div></header>
<main id="main">{body}</main><footer class="site-footer shell"><div><a class="footer-invite" href="{EMAIL}">Let’s build something useful. <span aria-hidden="true">↗</span></a><p>Software engineering & applied AI · Graduating May 2027</p></div><div class="footer-links"><a href="/assets/resume.pdf">Resume</a><a href="https://github.com/Mobi21">GitHub</a><a href="https://www.linkedin.com/in/mobolaji-ogunbiyi-355a53287/">LinkedIn</a><a href="/work-writing/">Writing</a></div><p class="copyright">© 2026 Mobolaji Ogunbiyi · Built with care in Maryland.</p></footer></body></html>'''
    dest=ROOT/route.strip('/')/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(html,encoding='utf-8')

def hero(title, desc, meta='', actions=''):
    return f'<section class="project-hero shell"><a class="back-link" href="/projects/">← All work</a><div class="project-heading"><h1>{title}</h1><p class="project-description">{desc}</p></div><div class="project-meta">{meta}</div><div class="action-row">{actions}</div></section>'

def section(title, content, id=''):
    return f'<section class="story-section shell"'+(f' id="{id}"' if id else '')+f'><h2>{title}</h2><div class="story-content">{content}</div></section>'

def ks_preview():
    return '''<div class="ks-preview" aria-label="Illustrated KS App workspace"><div class="ks-sidebar"><b>KS</b><span>Home</span><span class="selected">Projects</span><span>Clients</span><span>Finance</span><span>Knowledge</span></div><div class="ks-preview-main"><div class="ks-topline">Northstar Studio <span>Sample workspace</span></div><h3>Work, moving forward.</h3><div class="ks-preview-row"><b>Website refresh</b><span class="status">In progress</span></div><div class="ks-preview-row"><b>Client onboarding</b><span>In review</span></div><div class="ks-preview-row"><b>Brand guidelines</b><span>Planning</span></div><div class="ks-assistant-note"><span class="assistant-symbol">✦</span><div><b>Your next move, in context.</b><p>Client records, project work, and your AI operator. Together.</p></div></div></div></div>'''

